approaches.pseudocode:
positions = empty map
for i from 0 to n-1:
  if target - values[i] exists in positions:
    return [positions[target - values[i]], i]
  positions[values[i]] = i
return []

for i from 0 to n-1:
  for j from i+1 to n-1:
    if values[i]+values[j] == target: return [i,j]
return []

best = -infinity
for start in positions:
  sum = 0
  for end from start to n-1:
    sum += values[end]; best = max(best,sum)
return best

left = 0; right = n - 1
while left <= right:
  mid = floor((left + right)/2)
  if values[mid] == target: return mid
  if left half is sorted:
    keep left half if values[left] <= target < values[mid]
  else:
    keep right half if values[mid] < target <= values[right]
return -1

left = 0; best = 0; last = empty map
for right from 0 to n-1:
  if text[right] was seen: left = max(left, last[text[right]] + 1)
  last[text[right]] = right
  best = max(best, right-left+1)
return best

answers = n zeros; stack = []
for i from 0 to n-1:
  while stack nonempty and temperatures[stack.top] < temperatures[i]:
    j = pop; answers[j] = i-j
  push i
return answers

depth(node):
  if node is null: return 0
  return 1 + max(depth(node.left), depth(node.right))

valid(node, lower, upper):
  if node is null: return true
  if not lower < node.value < upper: return false
  return valid(node.left,lower,node.value) and valid(node.right,node.value,upper)
return valid(root,-infinity,+infinity)

count = 0
for every cell:
  if cell is unvisited land:
    count += 1
    flood all orthogonally connected land, marking visited
return count

result = [[]]
for value in values:
  oldSize = result.size
  for i from 0 to oldSize-1:
    append result[i] + [value]
return result

dp[0] = 0; all other entries = infinity
for subtotal from 1 to amount:
  for coin <= subtotal:
    dp[subtotal] = min(dp[subtotal], dp[subtotal-coin]+1)
return -1 if dp[amount] is infinity else dp[amount]

dp = n ones
for i from 0 to n-1:
  for j from 0 to i-1:
    if values[j] < values[i]: dp[i] = max(dp[i],dp[j]+1)
return max(dp), or 0 when empty

previous = zeros(length(second)+1)
for character in first:
  current[0] = 0
  for j from 1 to length(second):
    if character == second[j-1]: current[j] = previous[j-1]+1
    else: current[j] = max(previous[j],current[j-1])
  previous = current
return previous.last

dp[0] = true; all others false
for end from 1 to text.length:
  for word in words:
    if word fits and dp[end-word.length] and text suffix matches word:
      dp[end] = true; break
return dp[text.length]

put values in set
for x in set:
  if x-1 is absent:
    extend end while end+1 exists
    update best length
return best

write = 0
for value in values:
  if write == 0 or value != values[write-1]:
    values[write] = value; write++
return values[0:write]

words = nonempty tokens after splitting on spaces
reverse words
return join(words, single space)

for token in expression:
  if integer: push value
  else:
    right = pop; left = pop
    push left operator right, truncating division toward zero
return remaining stack value

for left in positions:
  minimum = infinity
  for right from left to n-1:
    minimum = min(minimum,height[right])
    update best with minimum*(right-left+1)

split path on slash
for component:
  ignore empty or single dot
  on double dot: pop if possible
  otherwise: push component
return slash + join(stack,slash)

for each original node: copies[original] = new node(original.value)
for each original node:
  copy.next = copies[original.next] or null
  copy.random = copies[original.random] or null
return copied head

for each node in main tree:
  if identicalTree(node, candidateRoot): return true
return candidateRoot is null

visit(start,path):
  if start == text.length: emit copy(path)
  for end from start+1 to text.length:
    if text[start:end] is palindrome:
      append piece; visit(end,path); remove piece

handle lengths zero and one directly
return max(linearBest(range excluding first),
           linearBest(range excluding last))

initialize dp to infinity; dp[0] = 0
for each row:
  for each column:
    dp[column] = cellCost + min(dp[column], leftCost or infinity)
return final dp entry

if total odd: return false
target = total/2; reachable[0] = true
for value in values:
  for sum from target down to value:
    reachable[sum] |= reachable[sum-value]
return reachable[target]

previous[j] = j
for i from 1 to first.length:
  current[0] = i
  for j from 1 to second.length:
    if characters match: copy diagonal
    else: 1 + min(deleteAbove,insertLeft,replaceDiagonal)
  previous = current
return previous[last]

ways[0] = 1; others zero
for coin in coins:
  for sum from coin to amount:
    ways[sum] += ways[sum-coin]
return ways[amount]

ways = {0:1}
for value in values:
  next = empty count map
  for sum,count in ways:
    next[sum+value] += count
    next[sum-value] += count
  ways = next
return ways[target] or zero

find the last index of each letter
start = end = 0
for i in positions:
  end = max(end,last[text[i]])
  if i == end: append i-start+1; start = i+1
return lengths

cost[0] = 0
for i from 1 to n-1:
  best = previousCost + abs(height[i]-height[i-1])
  if i>=2: compare twoBackCost + abs(height[i]-height[i-2])
  shift rolling costs
return last cost

distance = all -1; distance[0] = 0
queue = [0]
for each queued node:
  for each unseen neighbor:
    assign distance+1 and enqueue
return distance[nodes-1]
